text:
{
  "characters": [
    {
      "id": "hina",
      "want": "毎朝九時の観測を、閉鎖の日まで一度も欠かさず続けたい。",
      "need": "数字を書くことが町に届かないとしても、自分の字で日誌を閉じる責任を引き受けること。",
      "fear": "先代の日誌の書き換えに関わっていたと、あとから疑われること。",
      "wound": "叔父が死んだ日、日誌の最終頁を自分が書き足してしまったこと。",
      "secret": "三年前、空欄だった風速の欄に、うろ覚えの数字を書いた。",
      "principle": "測った値は、誰に聞かれても同じことを言う。",
      "self_view": "自分は代わりの観測員で、先代の記録を守る係だと思っている。",
      "others_view": [
        "サダから見れば、ツカサの手順を覚えている、ただ一人の若い観測員。",
        "黒沢から見れば、書類に判を押すだけの大人しい職員。"
      ],
      "predictions": [
        {"situation": "日誌の数字を町に確かめられたとき", "choice": "書き直さず、その頁の余白に測り直した時刻を足す。"},
        {"situation": "サダが日誌を渡さないと言ったとき", "choice": "せがまず、翌日もう一度だけ同じ頼み方をして帰る。"},
        {"situation": "閉鎖の日程を早めると告げられたとき", "choice": "抗議の電話をせず、閉じるまでの観測の段取りを先に紙に書く。"}
      ],
      "speech": {
        "sample": "九時、風向北、風速三・二。……先代の日誌だと、この欄、同じ日に二回書いてあるんです。",
        "vocab": ["九時", "三時", "日誌", "風速", "もう一度"],
        "avoid": ["運命", "奇跡", "きっと何とかなる", "感動"]
      },
      "arc": {
        "endpoint": "自分の書き足した数字を認めたうえで、最後の観測を自分の字で書いて日誌を閉じる。",
        "changed": ["先代の記録を無傷だと思い込むこと", "町に判断を委ねること"],
        "unchanged": ["朝九時に測ること", "聞かれたことに同じ答えを返すこと"]
      },
      "bans": ["涙で感情を示す", "黒沢を説教で論破する", "数字を勘で埋める"]
    },
    {
      "id": "sada",
      "want": "夫が集めた署名のことを、誰にも思い出させずに冬を越したい。",
      "need": "夫が何を書こうとしていたのかを、裁かれない形で一度だけ若い観測員に渡すこと。",
      "fear": "日誌を出したことで、夫が町に睨まれていた理由まで表に出ること。",
      "wound": "署名を町に出した日の夜、夫が黙って茶を飲み続けたこと。",
      "secret": "署名の控えを、日誌と一緒に引き出しへしまっている。",
      "principle": "人の家の引き出しは、本人が開けるまで開けない。",
      "self_view": "自分は夫の荷物を預かっているだけだと思っている。",
      "others_view": [
        "ヒナから見れば、何でも知っていて何も渡さない年寄り。",
        "黒沢から見れば、書類に判を押さないだけの障碍。"
      ],
      "predictions": [
        {"situation": "ヒナが日誌の話を出したとき", "choice": "話を逸らし、代わりに茶を入れ直す。"},
        {"situation": "黒沢が署名の有無を聞いてきたとき", "choice": "知らないと答え、仏壇の前から動かない。"},
        {"situation": "ヒナが三度目に訪ねてきたとき", "choice": "日誌だけを渡し、署名の控えは渡さない。"}
      ],
      "speech": {
        "sample": "その日誌はね、うちの人が最後まで抱えてたもんだ。あんたに渡すのは惜しくないよ。惜しいのは、あの人が何を書きたかったかだ。",
        "vocab": ["日誌", "うちの人", "引き出し", "茶", "惜しい"],
        "avoid": ["長い謝罪", "若者への説教", "感情の説明"]
      },
      "arc": {
        "endpoint": "日誌を渡し、署名の控えの存在だけを口にする。",
        "changed": ["日誌を隠し続けること"],
        "unchanged": ["引き出しを自分で開けること", "判を安易に押さないこと"]
      },
      "bans": ["自分から長く語り出す", "ヒナを抱きしめる", "夫の死を嘆き続ける"]
    },
    {
      "id": "kuro",
      "want": "年度内に閉鎖を終わらせ、転用の議案を通すこと。",
      "need": "閉鎖の理由を、予算の言葉だけでなく町の暮らしの言葉でも説明できるようになること。",
      "fear": "観測の数字が議会で持ち出され、計画が年度を越えること。",
      "wound": "前の担当で、説明を省いたために住民説明会が荒れたこと。",
      "secret": "閉鎖の理由に老朽化を挙げたのは、自分が書いた文面だった。",
      "principle": "書類は、町が生き延びる順序に並べる。",
      "self_view": "自分は町の暮らしを数字で守っている実務家だと思っている。",
      "others_view": [
        "ヒナから見れば、日誌を読まずに閉じようとする人。",
        "サダから見れば、夫を嫌っていた役場の若い衆。"
      ],
      "predictions": [
        {"situation": "ヒナが日誌の二重記載を指摘したとき", "choice": "訂正を求めず、写しを一枚だけ取らせる。"},
        {"situation": "議会で署名の話が出たとき", "choice": "隠さず、自分が受理したと認める。"},
        {"situation": "転用の議案が滞ったとき", "choice": "相手を責めず、縦覧の期間を延ばす。"}
      ],
      "speech": {
        "sample": "閉鎖はもう決まってるんです。老朽化って書いたのは私ですが、予算が動かないことには、観測を続けるお金も出ない。",
        "vocab": ["年度内", "議案", "予算", "縦覧", "写し"],
        "avoid": ["悪役の嘲笑", "ヒナを脅す", "数字の改ざん"]
      },
      "arc": {
        "endpoint": "閉鎖の理由を議会で自分の言葉で説明し、署名を受理していたことを認める。",
        "changed": ["老朽化という説明で押し切ること"],
        "unchanged": ["年度内に仕事を終えること", "書類の順序を自分で決めること"]
      },
      "bans": ["私利私欲の悪役として振る舞う", "日誌を破棄する", "ヒナを解任で脅す"]
    },
    {
      "id": "tsukasa",
      "want": "閉鎖の前に、署名を町へ出し切ること。",
      "need": "自分が書けなかった理由を、日誌の余白に手順として残すこと。",
      "fear": "署名が無かったことにされ、閉鎖が手続きだけで通ること。",
      "wound": "署名を出した日の夜、町の誰も反応しなかったこと。",
      "secret": "署名の控えを、妻にだけ預けたこと。",
      "principle": "書かなかったことは、無かったことと同じになる。",
      "self_view": "自分は最後まで観測員だったと思っている。",
      "others_view": [
        "ヒナから見れば、最終頁を書きかけで残した叔父。",
        "サダから見れば、黙って茶を飲み続けた夫。"
      ],
      "predictions": [
        {"situation": "署名を出した直後、町が動かなかったとき", "choice": "抗議せず、日誌の余白に日付だけを書く。"},
        {"situation": "ヒナに観測を教える段になったとき", "choice": "順序だけを口で伝え、理由は言わない。"},
        {"situation": "自分の病が重くなったとき", "choice": "日誌を閉じずに、机の上に置いたままにする。"}
      ],
      "speech": {
        "sample": "九時は風向からだ。風速を先に書くと、あとで読み返したときに順序が分からんくなる。",
        "vocab": ["九時", "順序", "日誌", "余白"],
        "avoid": ["現在の場面での発話", "未来の出来事への言及"]
      },
      "arc": {
        "endpoint": "三年前に既に終わっている。以後、行為者にも発話者にもならない。",
        "changed": ["なし（物語の現在では既に死んでいる）"],
        "unchanged": ["日誌の最終頁を書きかけのまま残したこと"]
      },
      "bans": ["現在の場面に登場する", "回想以外で発言する", "ヒナに直接語りかける"]
    }
  ]
}
